=encoding UTF-8

=head1 NAME

Google::Backstory::Udm - Compiled Protocol Buffers messages for backstory/udm.proto

=head1 SYNOPSIS

    use Google::Backstory::Udm;

    my $msg = Google::Backstory::Udm::UDM->new({
        metadata => $metadata,
        additional => $additional,
        principal => $principal,
        src => $src,
    });

    # Read or update a field
    my $val = $msg->metadata();

    # Binary wire-format roundtrip
    my $bytes   = $msg->serialize();
    my $decoded = Google::Backstory::Udm::UDM->parse($bytes);

    # Canonical ProtoJSON
    my $json = $msg->to_json();

=head1 DESCRIPTION

Auto-generated L<Protobuf> message classes compiled from C<backstory/udm.proto>. All message classes inherit from
L<Protobuf::Message> and support C<new()>, C<serialize()>, C<parse()>,
C<to_json()>, C<from_json()>, C<to_text()>, and C<to_perl()>.

=head1 MESSAGES

=head2 Google::Backstory::Udm::UDM

A Unified Data Model event.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->metadata() >> / C<< $msg->metadata($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Metadata>)

Event metadata such as timestamp, source product, etc.

=item * C<< $msg->additional() >> / C<< $msg->additional($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

Any important vendor-specific event data that cannot be adequately
represented within the formal sections of the UDM model.

=item * C<< $msg->principal() >> / C<< $msg->principal($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Noun>)

Represents the acting entity that originates the activity
described in the event. The principal must include at least one machine
detail (hostname, MACs, IPs, port, product-specific identifiers like an
EDR asset ID) or user detail (for example, username), and optionally
include process details. It must NOT include any of the following fields:
email, files, registry keys or values.

=item * C<< $msg->src() >> / C<< $msg->src($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Noun>)

Represents a source entity being acted upon by the participant along with
the device or process context for the source object (the machine where the
source object resides). For example, if user U copies file A on machine X
to file B on machine Y, both file A and machine X would be specified in the
src portion of the UDM event.

=item * C<< $msg->target() >> / C<< $msg->target($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Noun>)

Represents a target entity being referenced by the event or an object on
the target entity. For example, in a firewall connection from device A to
device B, A is described as the principal and B is described as the target.
For a process injection by process C into target process D, process C is
described as the principal and process D is described as the target.

=item * C<< $msg->intermediary() >> / C<< $msg->intermediary($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Noun>)

Represents details on one or more intermediate entities processing activity
described in the event. This includes device details about a proxy server
or SMTP relay server. If an active event (that has a principal and
possibly target) passes through any intermediaries, they're added here.
Intermediaries can impact the overall action, for example blocking or
modifying an ongoing request.  A rule of thumb here is that 'principal',
'target', and description of the initial action should be the same
regardless of the intermediary or its action.  A successful network
connection from A->B should look the same in principal/target/intermediary
as one blocked by firewall C: principal: A, target: B (intermediary: C).

=item * C<< $msg->observer() >> / C<< $msg->observer($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Noun>)

Represents an observer entity (for example, a packet sniffer or
network-based vulnerability scanner), which is not a direct intermediary,
but which observes and reports on the event in question.

=item * C<< $msg->about() >> / C<< $msg->about($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Noun>)

Represents entities referenced by the event that are not otherwise
described in principal, src, target, intermediary or observer. For example,
it could be used to track email file attachments, domains/URLs/IPs embedded
within an email body, and DLLs that are loaded during a PROCESS_LAUNCH
event.

=item * C<< $msg->security_result() >> / C<< $msg->security_result($value) >>

Type: C<Message> (L<Google::Backstory::Udm::SecurityResult>)

A list of security results.

=item * C<< $msg->network() >> / C<< $msg->network($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Network>)

All network details go here, including sub-messages with details on each
protocol (for example, DHCP, DNS, or HTTP).

=item * C<< $msg->extensions() >> / C<< $msg->extensions($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Extensions>)

All other first-class, event-specific metadata goes in this message.
Do not place protocol metadata in Extensions; put it in Network.

=item * C<< $msg->extracted() >> / C<< $msg->extracted($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

Flattened fields extracted from the log.

=item * C<< $msg->grouped() >> / C<< $msg->grouped($value) >>

Type: C<Message> (L<Google::Backstory::Udm::GroupedFields>)

Related UDM fields that are grouped together.

=back

=head2 Google::Backstory::Udm::Metadata

General information associated with a UDM event.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->id() >> / C<< $msg->id($value) >>

Type: C<Bytes>

ID of the UDM event. Can be used for raw and normalized event retrieval.

=item * C<< $msg->product_log_id() >> / C<< $msg->product_log_id($value) >>

Type: C<String>

A vendor-specific event identifier to uniquely identify the event (e.g. a
GUID).

=item * C<< $msg->event_timestamp() >> / C<< $msg->event_timestamp($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

The GMT timestamp when the event was generated.

=item * C<< $msg->event_timestamp_attributes() >> / C<< $msg->event_timestamp_attributes($value) >>

Type: C<Enum> (L<Google::Backstory::Metadata::EventTimestampAttribute>)

Attributes associated with event_timestamp. This field
is used to distinguish between different types of timestamps that can be
used to represent the event_timestamp.

=item * C<< $msg->collected_timestamp() >> / C<< $msg->collected_timestamp($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

The GMT timestamp when the event was collected by the vendor's local
collection infrastructure.

=item * C<< $msg->ingested_timestamp() >> / C<< $msg->ingested_timestamp($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

The GMT timestamp when the event was ingested (received) by Chronicle.

=item * C<< $msg->event_type() >> / C<< $msg->event_type($value) >>

Type: C<Enum> (L<Google::Backstory::Metadata::EventType>)

The event type.
If an event has multiple possible types, this specifies the most specific
type.

=item * C<< $msg->vendor_name() >> / C<< $msg->vendor_name($value) >>

Type: C<String>

The name of the product vendor.

=item * C<< $msg->product_name() >> / C<< $msg->product_name($value) >>

Type: C<String>

The name of the product.

=item * C<< $msg->product_version() >> / C<< $msg->product_version($value) >>

Type: C<String>

The version of the product.

=item * C<< $msg->product_event_type() >> / C<< $msg->product_event_type($value) >>

Type: C<String>

A short, descriptive, human-readable, product-specific event name or type
(e.g. "Scanned X", "User account created", "process_start").

=item * C<< $msg->product_deployment_id() >> / C<< $msg->product_deployment_id($value) >>

Type: C<String>

The deployment identifier assigned by the vendor for a product deployment.

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

A human-readable unparsable description of the event.

=item * C<< $msg->url_back_to_product() >> / C<< $msg->url_back_to_product($value) >>

Type: C<String>

A URL that takes the user to the source product console for this event.

=item * C<< $msg->ingestion_labels() >> / C<< $msg->ingestion_labels($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Label>)

User-configured ingestion metadata labels.

=item * C<< $msg->tags() >> / C<< $msg->tags($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Tags>)

Tags added by Chronicle after an event is parsed. It is an error to
populate this field from within a parser.

=item * C<< $msg->enrichment_state() >> / C<< $msg->enrichment_state($value) >>

Type: C<Enum> (L<Google::Backstory::Metadata::EnrichmentState>)

The enrichment state.

=item * C<< $msg->log_type() >> / C<< $msg->log_type($value) >>

Type: C<String>

The string value of log type.

=item * C<< $msg->base_labels() >> / C<< $msg->base_labels($value) >>

Type: C<Message> (L<Google::Backstory::DataAccess::DataAccessLabels>)

Data access labels on the base event.

=item * C<< $msg->enrichment_labels() >> / C<< $msg->enrichment_labels($value) >>

Type: C<Message> (L<Google::Backstory::DataAccess::DataAccessLabels>)

Data access labels from all the contextual events used to enrich the base
event.

=item * C<< $msg->structured_fields() >> / C<< $msg->structured_fields($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

Flattened fields extracted from the log.

=item * C<< $msg->parser_version() >> / C<< $msg->parser_version($value) >>

Type: C<String>

The version of the parser that generated this UDM event.

=back

