=head2 Google::Backstory::Udm::Attribute

Attribute is a container for generic entity attributes including common
attributes across core entities (such as, user or asset). For example, Cloud
is a generic entity attribute since it can apply to an asset (for example, a
VM) or a user (for example, an identity service account).

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->cloud() >> / C<< $msg->cloud($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Cloud>)

Cloud metadata attributes such as project ID, account ID, or organizational
hierarchy.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Label>)

Set of labels for the entity. Should only be used for product labels (for
example, Google Cloud resource labels or Azure AD sensitivity labels.
Should not be used for arbitrary key-value mappings.

=item * C<< $msg->permissions() >> / C<< $msg->permissions($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Permission>)

System permissions for IAM entity
(human principal, service account, group).

=item * C<< $msg->roles() >> / C<< $msg->roles($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Role>)

System IAM roles to be assumed by resources to use the role's permissions
for access control.

=item * C<< $msg->creation_time() >> / C<< $msg->creation_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Time the resource or entity was created or provisioned.

=item * C<< $msg->last_update_time() >> / C<< $msg->last_update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Time the resource or entity was last updated.

=back

=head2 Google::Backstory::Udm::Network

A network event.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->sent_bytes() >> / C<< $msg->sent_bytes($value) >>

Type: C<UInt64>

The number of bytes sent.

=item * C<< $msg->received_bytes() >> / C<< $msg->received_bytes($value) >>

Type: C<UInt64>

The number of bytes received.

=item * C<< $msg->total_bytes() >> / C<< $msg->total_bytes($value) >>

Type: C<Int64>

The number of total bytes.

=item * C<< $msg->sent_packets() >> / C<< $msg->sent_packets($value) >>

Type: C<Int64>

The number of packets sent.

=item * C<< $msg->received_packets() >> / C<< $msg->received_packets($value) >>

Type: C<Int64>

The number of packets received.

