=over 4

=item * C<< $msg->about() >> / C<< $msg->about($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Noun>)

If the vulnerability is about a specific noun (e.g. executable),
then add it here.

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Name of the vulnerability (e.g. "Unsupported OS Version detected").

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

Description of the vulnerability.

=item * C<< $msg->vendor() >> / C<< $msg->vendor($value) >>

Type: C<String>

Vendor of scan that discovered vulnerability.

=item * C<< $msg->scan_start_time() >> / C<< $msg->scan_start_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

If the vulnerability was discovered during an asset scan, then this
field should be populated with the time the scan started.
This field can be left unset if the start time is not available or not
applicable.

=item * C<< $msg->scan_end_time() >> / C<< $msg->scan_end_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

If the vulnerability was discovered during an asset scan, then this field
should be populated with the time the scan ended.
This field can be left unset if the end time is not available or not
applicable.

=item * C<< $msg->first_found() >> / C<< $msg->first_found($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Products that maintain a history of vuln scans should populate first_found
with the time that a scan first detected the vulnerability on this asset.

=item * C<< $msg->last_found() >> / C<< $msg->last_found($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Products that maintain a history of vuln scans should populate last_found
with the time that a scan last detected the vulnerability on this asset.

=item * C<< $msg->severity() >> / C<< $msg->severity($value) >>

Type: C<Enum> (L<Google::Backstory::Vulnerability::Severity>)

The severity of the vulnerability.

=item * C<< $msg->severity_details() >> / C<< $msg->severity_details($value) >>

Type: C<String>

Vendor-specific severity

=item * C<< $msg->cvss_base_score() >> / C<< $msg->cvss_base_score($value) >>

Type: C<Float>

CVSS Base Score in the range of 0.0 to 10.0.
Useful for sorting.

=item * C<< $msg->cvss_vector() >> / C<< $msg->cvss_vector($value) >>

Type: C<String>

Vector of CVSS properties (e.g. "AV:L/AC:H/Au:N/C:N/I:P/A:C")
Can be linked to via:
[https://nvd.nist.gov/vuln-metrics/cvss/v2-calculator](https://nvd.nist.gov/vuln-metrics/cvss/v2-calculator)

=item * C<< $msg->cvss_version() >> / C<< $msg->cvss_version($value) >>

Type: C<String>

Version of CVSS Vector/Score.

=item * C<< $msg->cve_id() >> / C<< $msg->cve_id($value) >>

Type: C<String>

Common Vulnerabilities and Exposures Id.
[https://en.wikipedia.org/wiki/Common_Vulnerabilities_and_Exposures](https://en.wikipedia.org/wiki/Common_Vulnerabilities_and_Exposures)
[https://cve.mitre.org/about/faqs.html#what_is_cve_id](https://cve.mitre.org/about/faqs.html#what_is_cve_id)

=item * C<< $msg->cve_description() >> / C<< $msg->cve_description($value) >>

Type: C<String>

Common Vulnerabilities and Exposures Description.
[https://cve.mitre.org/about/faqs.html#what_is_cve_record](https://cve.mitre.org/about/faqs.html#what_is_cve_record)

=item * C<< $msg->vendor_vulnerability_id() >> / C<< $msg->vendor_vulnerability_id($value) >>

Type: C<String>

Vendor specific vulnerability id (e.g. Microsoft security bulletin id).

=item * C<< $msg->vendor_knowledge_base_article_id() >> / C<< $msg->vendor_knowledge_base_article_id($value) >>

Type: C<String>

Vendor specific knowledge base article (e.g. "KBXXXXXX" from Microsoft).
[https://en.wikipedia.org/wiki/Microsoft_Knowledge_Base](https://en.wikipedia.org/wiki/Microsoft_Knowledge_Base)
[https://access.redhat.com/knowledgebase](https://access.redhat.com/knowledgebase)

=back

