=over 4

=item * C<< $msg->pid() >> / C<< $msg->pid($value) >>

Type: C<String>

The process ID.
This field can be used as an entity indicator for process entities.

=item * C<< $msg->parent_pid() >> / C<< $msg->parent_pid($value) >>

Type: C<String>

The ID of the parent process.
Deprecated: use parent_process.pid instead.

=item * C<< $msg->parent_process() >> / C<< $msg->parent_process($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Process>)

Information about the parent process.

=item * C<< $msg->file() >> / C<< $msg->file($value) >>

Type: C<Message> (L<Google::Backstory::Udm::File>)

Information about the file in use by the process.

=item * C<< $msg->command_line() >> / C<< $msg->command_line($value) >>

Type: C<String>

The command line command that created the process.
This field can be used as an entity indicator for process entities.

=item * C<< $msg->command_line_history() >> / C<< $msg->command_line_history($value) >>

Type: C<String>

The command line history of the process.

=item * C<< $msg->product_specific_process_id() >> / C<< $msg->product_specific_process_id($value) >>

Type: C<String>

A product specific process id.

=item * C<< $msg->access_mask() >> / C<< $msg->access_mask($value) >>

Type: C<UInt64>

A bit mask representing the level of access.

=item * C<< $msg->integrity_level_rid() >> / C<< $msg->integrity_level_rid($value) >>

Type: C<UInt64>

The Microsoft Windows integrity level relative ID (RID) of the process.

=item * C<< $msg->euid() >> / C<< $msg->euid($value) >>

Type: C<String>

The effective user ID of the process.

=item * C<< $msg->ruid() >> / C<< $msg->ruid($value) >>

Type: C<String>

The real user ID of the process.

=item * C<< $msg->egid() >> / C<< $msg->egid($value) >>

Type: C<String>

The effective group ID of the process.

=item * C<< $msg->rgid() >> / C<< $msg->rgid($value) >>

Type: C<String>

The real group ID of the process.

=item * C<< $msg->pgid() >> / C<< $msg->pgid($value) >>

Type: C<String>

The identifier that points to the process group ID leader.

=item * C<< $msg->session_leader_pid() >> / C<< $msg->session_leader_pid($value) >>

Type: C<String>

The process ID of the session leader process.

=item * C<< $msg->tty() >> / C<< $msg->tty($value) >>

Type: C<String>

The teletype terminal which the command was executed within.

=item * C<< $msg->token_elevation_type() >> / C<< $msg->token_elevation_type($value) >>

Type: C<Enum> (L<Google::Backstory::Process::TokenElevationType>)

The elevation type of the process on Microsoft Windows. This determines if
any privileges are removed when UAC is enabled.

=item * C<< $msg->product_specific_parent_process_id() >> / C<< $msg->product_specific_parent_process_id($value) >>

Type: C<String>

A product specific id for the parent process.
Please use parent_process.product_specific_process_id instead.

=item * C<< $msg->ipv6() >> / C<< $msg->ipv6($value) >>

Type: C<Bool>

This is used to determine if the process is an IPv6 process.

=item * C<< $msg->kernel_duration() >> / C<< $msg->kernel_duration($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

The kernel time spent in the process.

=item * C<< $msg->user_duration() >> / C<< $msg->user_duration($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

The user time spent in the process.

=item * C<< $msg->real_duration() >> / C<< $msg->real_duration($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

The real time spent in the process. This is the sum of the kernel and user
time.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Backstory::Process::State>)

The state of the process.

=back

