=head2 Google::Backstory::Udm::PeFileMetadata

Metadata about a Microsoft Windows Portable Executable.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->import_hash() >> / C<< $msg->import_hash($value) >>

Type: C<String>

Hash of PE imports.

=back

=head2 Google::Backstory::Udm::FileMetadata

Metadata about a file.
Place metadata about different file types here, for example data
from the Microsoft Windows VersionInfo block or digital signer details.
Use a different sub-message per file type.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->pe() >> / C<< $msg->pe($value) >>

Type: C<Message> (L<Google::Backstory::Udm::PeFileMetadata>)

Metadata for Microsoft Windows PE files.
Deprecate PeFileMetadata in favor of single File proto.

=back

=head2 Google::Backstory::Udm::File

Information about a file.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->sha256() >> / C<< $msg->sha256($value) >>

Type: C<String>

The SHA256 hash of the file, as a hex-encoded string.
This field can be used as an entity indicator for file entities.

=item * C<< $msg->md5() >> / C<< $msg->md5($value) >>

Type: C<String>

The MD5 hash of the file, as a hex-encoded string.
This field can be used as an entity indicator for file entities.

=item * C<< $msg->sha1() >> / C<< $msg->sha1($value) >>

Type: C<String>

The SHA1 hash of the file, as a hex-encoded string.
This field can be used as an entity indicator for file entities.

=item * C<< $msg->size() >> / C<< $msg->size($value) >>

Type: C<UInt64>

The size of the file in bytes.

=item * C<< $msg->full_path() >> / C<< $msg->full_path($value) >>

Type: C<String>

The full path identifying the location of the file on the system.
This field can be used as an entity indicator for file entities.

=item * C<< $msg->mime_type() >> / C<< $msg->mime_type($value) >>

Type: C<String>

The MIME (Multipurpose Internet Mail Extensions) type of the file,
for example "PE", "PDF", or "powershell script".

=item * C<< $msg->file_metadata() >> / C<< $msg->file_metadata($value) >>

Type: C<Message> (L<Google::Backstory::Udm::FileMetadata>)

Metadata associated with the file.
Deprecate FileMetadata in favor of using fields in File.

=item * C<< $msg->security_result() >> / C<< $msg->security_result($value) >>

Type: C<Message> (L<Google::Backstory::Udm::SecurityResult>)

Google Cloud Threat Intelligence (GCTI) security result for the file
including threat context and detection metadata.

=item * C<< $msg->pe_file() >> / C<< $msg->pe_file($value) >>

Type: C<Message> (L<Google::Backstory::Udm::FileMetadataPE>)

Metadata about the Portable Executable (PE) file.

=item * C<< $msg->ssdeep() >> / C<< $msg->ssdeep($value) >>

Type: C<String>

Ssdeep of the file

=item * C<< $msg->vhash() >> / C<< $msg->vhash($value) >>

Type: C<String>

Vhash of the file.

=item * C<< $msg->ahash() >> / C<< $msg->ahash($value) >>

Type: C<String>

Deprecated. Use authentihash instead.

=item * C<< $msg->authentihash() >> / C<< $msg->authentihash($value) >>

Type: C<String>

Authentihash of the file.

=item * C<< $msg->symhash() >> / C<< $msg->symhash($value) >>

Type: C<String>

SymHash of the file. Used for Mach-O (e.g. MacOS) binaries, to identify
similar files based on their symbol table.

=item * C<< $msg->prefetch_file_metadata() >> / C<< $msg->prefetch_file_metadata($value) >>

Type: C<Message> (L<Google::Backstory::Udm::PrefetchFileMetadata>)

Metadata about the prefetch file.

=item * C<< $msg->file_type() >> / C<< $msg->file_type($value) >>

Type: C<Enum> (L<Google::Backstory::File::FileType>)

FileType field.

=item * C<< $msg->capabilities_tags() >> / C<< $msg->capabilities_tags($value) >>

Type: C<String>

Capabilities tags.

=item * C<< $msg->names() >> / C<< $msg->names($value) >>

Type: C<String>

Names fields.

=item * C<< $msg->tags() >> / C<< $msg->tags($value) >>

Type: C<String>

Tags for the file.

=item * C<< $msg->last_modification_time() >> / C<< $msg->last_modification_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Timestamp when the file was last updated.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Timestamp when the file was created.

=item * C<< $msg->last_access_time() >> / C<< $msg->last_access_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Timestamp when the file was accessed.

=item * C<< $msg->prevalence() >> / C<< $msg->prevalence($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Prevalence>)

Prevalence of the file hash in the customer's environment.

=item * C<< $msg->first_seen_time() >> / C<< $msg->first_seen_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Timestamp the file was first seen in the customer's environment.

=item * C<< $msg->last_seen_time() >> / C<< $msg->last_seen_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Timestamp the file was last seen in the customer's environment.

=item * C<< $msg->stat_mode() >> / C<< $msg->stat_mode($value) >>

Type: C<UInt64>

The mode of the file. A bit string indicating the permissions and
privileges of the file.

=item * C<< $msg->stat_inode() >> / C<< $msg->stat_inode($value) >>

Type: C<UInt64>

The file identifier. Unique identifier of object within a file system.

=item * C<< $msg->stat_dev() >> / C<< $msg->stat_dev($value) >>

Type: C<UInt64>

The file system identifier to which the object belongs.

=item * C<< $msg->stat_nlink() >> / C<< $msg->stat_nlink($value) >>

Type: C<UInt64>

Number of links to file.

=item * C<< $msg->stat_flags() >> / C<< $msg->stat_flags($value) >>

Type: C<UInt32>

User defined flags for file.

=item * C<< $msg->last_analysis_time() >> / C<< $msg->last_analysis_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Timestamp the file was last analysed.

=item * C<< $msg->embedded_urls() >> / C<< $msg->embedded_urls($value) >>

Type: C<String>

Embedded urls found in the file.

=item * C<< $msg->embedded_domains() >> / C<< $msg->embedded_domains($value) >>

Type: C<String>

Embedded domains found in the file.

=item * C<< $msg->embedded_ips() >> / C<< $msg->embedded_ips($value) >>

Type: C<String>

Embedded IP addresses found in the file.

=item * C<< $msg->exif_info() >> / C<< $msg->exif_info($value) >>

Type: C<Message> (L<Google::Backstory::Udm::ExifInfo>)

Exif metadata from different file formats extracted by exiftool.

=item * C<< $msg->signature_info() >> / C<< $msg->signature_info($value) >>

Type: C<Message> (L<Google::Backstory::Udm::SignatureInfo>)

File signature information extracted from different tools.

=item * C<< $msg->pdf_info() >> / C<< $msg->pdf_info($value) >>

Type: C<Message> (L<Google::Backstory::Udm::PDFInfo>)

Information about the PDF file structure.

=item * C<< $msg->first_submission_time() >> / C<< $msg->first_submission_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

First submission time of the file.

=item * C<< $msg->last_submission_time() >> / C<< $msg->last_submission_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Last submission time of the file.

=item * C<< $msg->main_icon() >> / C<< $msg->main_icon($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Favicon>)

Icon's relevant hashes.

=item * C<< $msg->ntfs() >> / C<< $msg->ntfs($value) >>

Type: C<Message> (L<Google::Backstory::Udm::NtfsFileMetadata>)

NTFS metadata.

=item * C<< $msg->app_compat_cache() >> / C<< $msg->app_compat_cache($value) >>

Type: C<Message> (L<Google::Backstory::Udm::AppCompatMetadata>)

Windows AppCompatCache (Application Compatibility) metadata.

=back

