Signature information.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->verification_message() >> / C<< $msg->verification_message($value) >>

Type: C<String>

Status of the certificate.
Valid values are "Signed", "Unsigned" or a description of the certificate
anomaly, if found.

=item * C<< $msg->verified() >> / C<< $msg->verified($value) >>

Type: C<Bool>

True if verification_message == "Signed"

=item * C<< $msg->signer() >> / C<< $msg->signer($value) >>

Type: C<String>

Deprecated: use signers field.

=item * C<< $msg->signers() >> / C<< $msg->signers($value) >>

Type: C<Message> (L<Google::Backstory::Udm::SignerInfo>)

File metadata signer information.
The order of the signers matters. Each element is a higher level
authority, being the last the root authority.

=item * C<< $msg->x509() >> / C<< $msg->x509($value) >>

Type: C<Message> (L<Google::Backstory::Udm::X509>)

List of certificates.

=back

=head2 Google::Backstory::Udm::SignerInfo

File metadata related to the signer information.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Common name of the signers/certificate.
The order of the signers matters. Each element is a higher level
authority, the last being the root authority.

=item * C<< $msg->status() >> / C<< $msg->status($value) >>

Type: C<String>

It can say "Valid" or state the problem with the certificate if any (e.g.
"This certificate or one of the certificates in the certificate chain is
not time valid.").

=item * C<< $msg->valid_usage() >> / C<< $msg->valid_usage($value) >>

Type: C<String>

Indicates which situations the certificate is valid for (e.g. "Code
Signing").

=item * C<< $msg->cert_issuer() >> / C<< $msg->cert_issuer($value) >>

Type: C<String>

Company that issued the certificate.

=back

