Type: C<Int64>

Number of /JavaScript tags found in the PDF file. Should be the same as
the js field in normal scenarios.

=item * C<< $msg->launch_action_count() >> / C<< $msg->launch_action_count($value) >>

Type: C<Int64>

Number of /Launch tags found in the PDF file.

=item * C<< $msg->object_stream_count() >> / C<< $msg->object_stream_count($value) >>

Type: C<Int64>

Number of object streams.

=item * C<< $msg->endobj_count() >> / C<< $msg->endobj_count($value) >>

Type: C<Int64>

Number of object definitions (endobj keyword).

=item * C<< $msg->header() >> / C<< $msg->header($value) >>

Type: C<String>

PDF version.

=item * C<< $msg->acroform() >> / C<< $msg->acroform($value) >>

Type: C<Int64>

Number of /AcroForm tags found in the PDF.

=item * C<< $msg->autoaction() >> / C<< $msg->autoaction($value) >>

Type: C<Int64>

Number of /AA tags found in the PDF.

=item * C<< $msg->embedded_file() >> / C<< $msg->embedded_file($value) >>

Type: C<Int64>

Number of /EmbeddedFile tags found in the PDF.

=item * C<< $msg->encrypted() >> / C<< $msg->encrypted($value) >>

Type: C<Int64>

Whether the document is encrypted or not. This is defined by the /Encrypt
tag.

=item * C<< $msg->flash() >> / C<< $msg->flash($value) >>

Type: C<Int64>

Number of /RichMedia tags found in the PDF.

=item * C<< $msg->jbig2_compression() >> / C<< $msg->jbig2_compression($value) >>

Type: C<Int64>

Number of /JBIG2Decode tags found in the PDF.

=item * C<< $msg->obj_count() >> / C<< $msg->obj_count($value) >>

Type: C<Int64>

Number of objects definitions (obj keyword).

=item * C<< $msg->endstream_count() >> / C<< $msg->endstream_count($value) >>

Type: C<Int64>

Number of defined stream objects (stream keyword).

=item * C<< $msg->page_count() >> / C<< $msg->page_count($value) >>

Type: C<Int64>

Number of pages in the PDF.

=item * C<< $msg->stream_count() >> / C<< $msg->stream_count($value) >>

Type: C<Int64>

Number of defined stream objects (stream keyword).

=item * C<< $msg->openaction() >> / C<< $msg->openaction($value) >>

Type: C<Int64>

Number of /OpenAction tags found in the PDF.

=item * C<< $msg->startxref() >> / C<< $msg->startxref($value) >>

Type: C<Int64>

Number of startxref keywords in the PDF.

=item * C<< $msg->suspicious_colors() >> / C<< $msg->suspicious_colors($value) >>

Type: C<Int64>

Number of colors expressed with more than 3 bytes (CVE-2009-3459).

=item * C<< $msg->trailer() >> / C<< $msg->trailer($value) >>

Type: C<Int64>

Number of trailer keywords in the PDF.

=item * C<< $msg->xfa() >> / C<< $msg->xfa($value) >>

Type: C<Int64>

Number of \XFA tags found in the PDF.

=item * C<< $msg->xref() >> / C<< $msg->xref($value) >>

Type: C<Int64>

Number of xref keywords in the PDF.

=back

