=head2 Google::Backstory::Udm::Prevalence

The prevalence of a resource within the customer's environment.
This measures how common it is for assets to access the resource.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->rolling_max() >> / C<< $msg->rolling_max($value) >>

Type: C<Int32>

The maximum number of assets per day accessing the resource over the
trailing day_count days.

=item * C<< $msg->day_count() >> / C<< $msg->day_count($value) >>

Type: C<Int32>

The number of days over which rolling_max is calculated.

=item * C<< $msg->rolling_max_sub_domains() >> / C<< $msg->rolling_max_sub_domains($value) >>

Type: C<Int32>

The maximum number of assets per day accessing the domain along with
sub-domains over the trailing day_count days. This field is only valid for
domains.

=item * C<< $msg->day_max() >> / C<< $msg->day_max($value) >>

Type: C<Int32>

The max prevalence score in a day interval window.

=item * C<< $msg->day_max_sub_domains() >> / C<< $msg->day_max_sub_domains($value) >>

Type: C<Int32>

The max prevalence score in a day interval window across sub-domains. This
field is only valid for domains.

=back

=head2 Google::Backstory::Udm::Dns

DNS information.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->id() >> / C<< $msg->id($value) >>

Type: C<UInt32>

DNS query id.

=item * C<< $msg->response() >> / C<< $msg->response($value) >>

Type: C<Bool>

Set to true if the event is a DNS response. See QR field from RFC1035.

=item * C<< $msg->opcode() >> / C<< $msg->opcode($value) >>

Type: C<UInt32>

The DNS OpCode used to specify the type of DNS query
(for example, QUERY, IQUERY, or STATUS).

=item * C<< $msg->authoritative() >> / C<< $msg->authoritative($value) >>

Type: C<Bool>

Other DNS header flags. See RFC1035, section 4.1.1.

=item * C<< $msg->truncated() >> / C<< $msg->truncated($value) >>

Type: C<Bool>

Whether the DNS response was truncated.

=item * C<< $msg->recursion_desired() >> / C<< $msg->recursion_desired($value) >>

Type: C<Bool>

Whether a recursive DNS lookup is desired.

=item * C<< $msg->recursion_available() >> / C<< $msg->recursion_available($value) >>

Type: C<Bool>

Whether a recursive DNS lookup is available.

=item * C<< $msg->response_code() >> / C<< $msg->response_code($value) >>

Type: C<UInt32>

Response code. See RCODE from RFC1035.

=item * C<< $msg->questions() >> / C<< $msg->questions($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Dns::Question>)

A list of domain protocol message questions.

=item * C<< $msg->answers() >> / C<< $msg->answers($value) >>

