Type: C<Message> (L<Google::Backstory::Udm::Dns::ResourceRecord>)

A list of domain name servers which verified the answers to the domain name
queries.

=item * C<< $msg->additional() >> / C<< $msg->additional($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Dns::ResourceRecord>)

