Type: C<UInt32>

Transaction ID.

=item * C<< $msg->seconds() >> / C<< $msg->seconds($value) >>

Type: C<UInt32>

Seconds elapsed since client began address acquisition/renewal process.

=item * C<< $msg->flags() >> / C<< $msg->flags($value) >>

Type: C<UInt32>

Flags.

=item * C<< $msg->ciaddr() >> / C<< $msg->ciaddr($value) >>

Type: C<String>

Client IP address (ciaddr).

=item * C<< $msg->yiaddr() >> / C<< $msg->yiaddr($value) >>

Type: C<String>

Your IP address (yiaddr).

=item * C<< $msg->siaddr() >> / C<< $msg->siaddr($value) >>

Type: C<String>

