=item * C<< $msg->file() >> / C<< $msg->file($value) >>

Type: C<String>

Boot image filename.

=item * C<< $msg->options() >> / C<< $msg->options($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Dhcp::Option>)

List of DHCP options.

=item * C<< $msg->type() >> / C<< $msg->type($value) >>

Type: C<Enum> (L<Google::Backstory::Dhcp::MessageType>)

DHCP message type.

=item * C<< $msg->lease_time_seconds() >> / C<< $msg->lease_time_seconds($value) >>

Type: C<UInt32>

Lease time in seconds. See RFC2132, section 9.2.

=item * C<< $msg->client_hostname() >> / C<< $msg->client_hostname($value) >>

Type: C<String>

Client hostname. See RFC2132, section 3.14.

=item * C<< $msg->client_identifier() >> / C<< $msg->client_identifier($value) >>

Type: C<Bytes>

Client identifier. See RFC2132, section 9.14.
Note: Make sure to update the client_identifier_string field as well if you
update this field.

=item * C<< $msg->requested_address() >> / C<< $msg->requested_address($value) >>

Type: C<String>

Requested IP address. See RFC2132, section 9.1.

=item * C<< $msg->client_identifier_string() >> / C<< $msg->client_identifier_string($value) >>

Type: C<String>

Client identifier as string. See RFC2132, section 9.14.
This field holds the string value of the client_identifier.

