=head2 Google::Backstory::Udm::Browser

Information about an entry in the web browser's local history database.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->browser_type() >> / C<< $msg->browser_type($value) >>

Type: C<Enum> (L<Google::Backstory::Browser::BrowserType>)

The browser that recorded the history entry (e.g. "Chrome", "Firefox",
"Safari", etc.).

=item * C<< $msg->browser_version() >> / C<< $msg->browser_version($value) >>

Type: C<String>

The browser version.

=item * C<< $msg->first_visit_time() >> / C<< $msg->first_visit_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

The timestamp indicating the initial visit to the URL.

=item * C<< $msg->last_visit_time() >> / C<< $msg->last_visit_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

The timestamp indicating the most recent visit to the URL.

=item * C<< $msg->profile() >> / C<< $msg->profile($value) >>

Type: C<String>

The browser profile associated with the history entry.

=item * C<< $msg->typed() >> / C<< $msg->typed($value) >>

Type: C<Bool>

A boolean value indicating if the URL was typed by the user.

=item * C<< $msg->visit_type() >> / C<< $msg->visit_type($value) >>

Type: C<Enum> (L<Google::Backstory::Browser::UrlVisitType>)

Describes the type of navigation or visit (e.g., direct, redirect, etc.).

=item * C<< $msg->hidden() >> / C<< $msg->hidden($value) >>

Type: C<Bool>

A boolean value indicating if the history entry is hidden.

=item * C<< $msg->request_origin_uri() >> / C<< $msg->request_origin_uri($value) >>

Type: C<String>

Indicates the URI from which the current visit originated.

=item * C<< $msg->visit_count() >> / C<< $msg->visit_count($value) >>

Type: C<Int64>

The total number of times the Url has been visited.

=item * C<< $msg->visit_count_criteria() >> / C<< $msg->visit_count_criteria($value) >>

Type: C<String>

Describes the criteria used to calculate the visit_count.

=item * C<< $msg->indexed_content() >> / C<< $msg->indexed_content($value) >>

Type: C<String>

Represents the textual content of a web page. This field should be kept
short. Large strings may affect latency and payload sizes.

=item * C<< $msg->first_bookmarked_time() >> / C<< $msg->first_bookmarked_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

The timestamp indicating the first time the URL was bookmarked.

=item * C<< $msg->cookies() >> / C<< $msg->cookies($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Browser::Cookie>)

Information about the cookies.

=item * C<< $msg->typed_count() >> / C<< $msg->typed_count($value) >>

Type: C<Int64>

The number of times the URL was visited with this specific visit type and
visit source.

=item * C<< $msg->visit_source() >> / C<< $msg->visit_source($value) >>

Type: C<Enum> (L<Google::Backstory::Browser::VisitSource>)

The source of the visit.

=back

