=head2 Google::Backstory::Udm::Asset

Information about a compute asset such as a workstation, laptop, phone,
virtual desktop, or VM.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->product_object_id() >> / C<< $msg->product_object_id($value) >>

Type: C<String>

A vendor-specific identifier to uniquely identify the entity (a GUID  or
similar).
This field can be used as an entity indicator for asset entities.

=item * C<< $msg->hostname() >> / C<< $msg->hostname($value) >>

Type: C<String>

Asset hostname or domain name field.
This field can be used as an entity indicator for asset entities.

=item * C<< $msg->asset_id() >> / C<< $msg->asset_id($value) >>

Type: C<String>

The asset ID. Value must contain the ':' character. For example,
cs:abcdd23434.
This field can be used as an entity indicator for asset entities.

=item * C<< $msg->ip() >> / C<< $msg->ip($value) >>

Type: C<String>

A list of IP addresses associated with an asset.
This field can be used as an entity indicator for asset entities.

=item * C<< $msg->mac() >> / C<< $msg->mac($value) >>

Type: C<String>

List of MAC addresses associated with an asset.
This field can be used as an entity indicator for asset entities.

=item * C<< $msg->nat_ip() >> / C<< $msg->nat_ip($value) >>

Type: C<String>

List of NAT IP addresses associated with an asset.

=item * C<< $msg->first_seen_time() >> / C<< $msg->first_seen_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

The first observed time for an asset.
The value is calculated on the basis of the
first time the identifier was observed.

=item * C<< $msg->hardware() >> / C<< $msg->hardware($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Hardware>)

The asset hardware specifications.

=item * C<< $msg->platform_software() >> / C<< $msg->platform_software($value) >>

Type: C<Message> (L<Google::Backstory::Udm::PlatformSoftware>)

The asset operating system platform software.

=item * C<< $msg->software() >> / C<< $msg->software($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Software>)

The asset software details.

=item * C<< $msg->location() >> / C<< $msg->location($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Location>)

Location of the asset.

=item * C<< $msg->category() >> / C<< $msg->category($value) >>

Type: C<String>

The category of the asset (e.g. "End User Asset", "Workstation", "Server").

=item * C<< $msg->type() >> / C<< $msg->type($value) >>

Type: C<Enum> (L<Google::Backstory::Asset::AssetType>)

The type of the asset (e.g. workstation or laptop or server).

=item * C<< $msg->network_domain() >> / C<< $msg->network_domain($value) >>

Type: C<String>

The network domain of the asset (e.g. "corp.acme.com")

=item * C<< $msg->creation_time() >> / C<< $msg->creation_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Time the asset was created or provisioned.
Deprecate: creation_time should be populated in Attribute as generic
metadata.

=item * C<< $msg->first_discover_time() >> / C<< $msg->first_discover_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Time the asset was first discovered (by asset management/discoverability
software).

=item * C<< $msg->last_discover_time() >> / C<< $msg->last_discover_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Time the asset was last discovered (by asset management/discoverability
software).

=item * C<< $msg->system_last_update_time() >> / C<< $msg->system_last_update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Time the asset system or OS was last updated.
For all other operations that are not system updates (such as resizing a
VM), use Attribute.last_update_time.

=item * C<< $msg->last_boot_time() >> / C<< $msg->last_boot_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Time the asset was last boot started.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Label>)

Metadata labels for the asset.
Deprecated: labels should be populated in Attribute as generic metadata.

=item * C<< $msg->deployment_status() >> / C<< $msg->deployment_status($value) >>

Type: C<Enum> (L<Google::Backstory::Asset::DeploymentStatus>)

The deployment status of the asset for device lifecycle purposes.

=item * C<< $msg->vulnerabilities() >> / C<< $msg->vulnerabilities($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Vulnerability>)

Vulnerabilities discovered on asset.

=item * C<< $msg->attribute() >> / C<< $msg->attribute($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Attribute>)

Generic entity metadata attributes of the asset.

=item * C<< $msg->wmi_persistence_item() >> / C<< $msg->wmi_persistence_item($value) >>

Type: C<Message> (L<Google::Backstory::Udm::WmiPersistenceItem>)

Information about a WMI persistence item.

=back

