=head2 Google::Backstory::Udm::User

Information about a user.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->product_object_id() >> / C<< $msg->product_object_id($value) >>

Type: C<String>

A vendor-specific identifier to uniquely identify the entity (e.g. a GUID,
LDAP, OID, or similar).
This field can be used as an entity indicator for user entities.

=item * C<< $msg->userid() >> / C<< $msg->userid($value) >>

Type: C<String>

The ID of the user.
This field can be used as an entity indicator for user entities.

=item * C<< $msg->user_display_name() >> / C<< $msg->user_display_name($value) >>

Type: C<String>

The display name of the user
(e.g. "John Locke").

=item * C<< $msg->first_name() >> / C<< $msg->first_name($value) >>

Type: C<String>

First name of the user (e.g. "John").

=item * C<< $msg->middle_name() >> / C<< $msg->middle_name($value) >>

Type: C<String>

Middle name of the user.

=item * C<< $msg->last_name() >> / C<< $msg->last_name($value) >>

Type: C<String>

Last name of the user (e.g. "Locke").

=item * C<< $msg->phone_numbers() >> / C<< $msg->phone_numbers($value) >>

Type: C<String>

Phone numbers for the user.

=item * C<< $msg->personal_address() >> / C<< $msg->personal_address($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Location>)

Personal address of the user.

=item * C<< $msg->attribute() >> / C<< $msg->attribute($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Attribute>)

Generic entity metadata attributes of the user.

=item * C<< $msg->first_seen_time() >> / C<< $msg->first_seen_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

The first observed time for a user.
The value is calculated on the basis of the
first time the identifier was observed.

=item * C<< $msg->account_type() >> / C<< $msg->account_type($value) >>

Type: C<Enum> (L<Google::Backstory::User::AccountType>)

Type of user account (for example, service, domain, or cloud). This is
somewhat aligned to:
[https://attack.mitre.org/techniques/T1078/](https://attack.mitre.org/techniques/T1078/)

=item * C<< $msg->groupid() >> / C<< $msg->groupid($value) >>

Type: C<String>

The ID of the group that the user belongs to.
Deprecated in favor of the repeated group_identifiers field.

=item * C<< $msg->group_identifiers() >> / C<< $msg->group_identifiers($value) >>

Type: C<String>

Product object identifiers of the group(s) the user belongs to
A vendor-specific identifier to uniquely identify the group(s) the user
belongs to (a GUID, LDAP OID, or similar).

