=head2 Google::Backstory::Udm::Noun

The Noun type is used to represent the different entities in an event:
principal, src, target, observer, intermediary, and about. It stores
attributes known about the entity. For example, if the entity is a device
with multiple IP or MAC addresses, it stores the IP and MAC addresses that
are relevant to the event.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->hostname() >> / C<< $msg->hostname($value) >>

Type: C<String>

Client hostname or domain name field.
Hostname also doubles as the domain for remote entities.
This field can be used as an entity indicator for asset entities.

=item * C<< $msg->domain() >> / C<< $msg->domain($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Domain>)

Information about the domain.

=item * C<< $msg->artifact() >> / C<< $msg->artifact($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Artifact>)

Information about an artifact.

=item * C<< $msg->url_metadata() >> / C<< $msg->url_metadata($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Url>)

Information about the URL.

=item * C<< $msg->browser() >> / C<< $msg->browser($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Browser>)

Information about an entry in the web browser's local history database.

=item * C<< $msg->asset_id() >> / C<< $msg->asset_id($value) >>

Type: C<String>

The asset ID.
This field can be used as an entity indicator for asset entities.

=item * C<< $msg->user() >> / C<< $msg->user($value) >>

Type: C<Message> (L<Google::Backstory::Udm::User>)

Information about the user.

=item * C<< $msg->user_management_chain() >> / C<< $msg->user_management_chain($value) >>

Type: C<Message> (L<Google::Backstory::Udm::User>)

Information about the user's management chain (reporting hierarchy).
Note: user_management_chain is only populated when data is exported to
BigQuery since recursive fields (e.g. user.managers) are not supported by
BigQuery.

=item * C<< $msg->group() >> / C<< $msg->group($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Group>)

Information about the group.

=item * C<< $msg->process() >> / C<< $msg->process($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Process>)

Information about the process.

=item * C<< $msg->process_ancestors() >> / C<< $msg->process_ancestors($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Process>)

Information about the process's ancestors ordered from immediate ancestor
(parent process) to root.
Note: process_ancestors is only populated when data is exported to BigQuery
since recursive fields (e.g. process.parent_process) are not supported by
BigQuery.

=item * C<< $msg->asset() >> / C<< $msg->asset($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Asset>)

Information about the asset.

=item * C<< $msg->ip() >> / C<< $msg->ip($value) >>

Type: C<String>

A list of IP addresses associated with a network connection.
This field can be used as an entity indicator for asset entities.

=item * C<< $msg->nat_ip() >> / C<< $msg->nat_ip($value) >>

Type: C<String>

A list of NAT translated IP addresses associated with a network connection.

=item * C<< $msg->port() >> / C<< $msg->port($value) >>

Type: C<Int32>

Source or destination network port number when a specific network
connection is described within an event.

=item * C<< $msg->nat_port() >> / C<< $msg->nat_port($value) >>

Type: C<Int32>

NAT external network port number when a specific network connection is
described within an event.

=item * C<< $msg->mac() >> / C<< $msg->mac($value) >>

Type: C<String>

List of MAC addresses associated with a device.
This field can be used as an entity indicator for asset entities.

=item * C<< $msg->administrative_domain() >> / C<< $msg->administrative_domain($value) >>

Type: C<String>

Domain which the device belongs to (for example, the Microsoft Windows
domain).

=item * C<< $msg->namespace() >> / C<< $msg->namespace($value) >>

Type: C<String>

Namespace which the device belongs to, such as "AD forest".
Uses for this field include Microsoft Windows AD forest, the name of
subsidiary, or the name of acquisition.
This field can be used along with an asset indicator to identify an asset.

=item * C<< $msg->url() >> / C<< $msg->url($value) >>

Type: C<String>

The URL.

=item * C<< $msg->file() >> / C<< $msg->file($value) >>

Type: C<Message> (L<Google::Backstory::Udm::File>)

Information about the file.

=item * C<< $msg->email() >> / C<< $msg->email($value) >>

Type: C<String>

Email address.
Only filled in for security_result.about

=item * C<< $msg->registry() >> / C<< $msg->registry($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Registry>)

Registry information.

=item * C<< $msg->application() >> / C<< $msg->application($value) >>

Type: C<String>

The name of an application or service.
Some SSO solutions only capture the name of a target application
such as "Atlassian" or "Chronicle".

=item * C<< $msg->platform() >> / C<< $msg->platform($value) >>

Type: C<Enum> (L<Google::Backstory::Noun::Platform>)

Platform.

=item * C<< $msg->platform_version() >> / C<< $msg->platform_version($value) >>

Type: C<String>

Platform version. For example,
"Microsoft Windows 1803".

=item * C<< $msg->platform_patch_level() >> / C<< $msg->platform_patch_level($value) >>

Type: C<String>

Platform patch level.
For example, "Build 17134.48"

=item * C<< $msg->cloud() >> / C<< $msg->cloud($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Cloud>)

Cloud metadata.
Deprecated: cloud should be populated in entity Attribute as generic
metadata (e.g. asset.attribute.cloud).

=item * C<< $msg->location() >> / C<< $msg->location($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Location>)

Physical location. For cloud environments, set the region in
location.name.

=item * C<< $msg->ip_location() >> / C<< $msg->ip_location($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Location>)

Deprecated: use ip_geo_artifact.location instead.

=item * C<< $msg->ip_geo_artifact() >> / C<< $msg->ip_geo_artifact($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Artifact>)

Enriched geographic information corresponding to an IP address.
Specifically, location and network data.

=item * C<< $msg->resource() >> / C<< $msg->resource($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Resource>)

Information about the resource (e.g. scheduled task, calendar entry).
This field should not be used for files, registry, or processes because
these objects are already part of Noun.

=item * C<< $msg->resource_ancestors() >> / C<< $msg->resource_ancestors($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Resource>)

Information about the resource's ancestors ordered from immediate ancestor
(starting with parent resource).

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Label>)

Labels are key-value pairs.
For example: key = "env", value = "prod".
Deprecated: labels should be populated in entity Attribute as generic
metadata (e.g. user.attribute.labels).

=item * C<< $msg->object_reference() >> / C<< $msg->object_reference($value) >>

Type: C<Message> (L<Google::Backstory::Id::Id>)

Finding to which the Analyst updated the feedback.

=item * C<< $msg->investigation() >> / C<< $msg->investigation($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Investigation>)

Analyst feedback/investigation for alerts.

=item * C<< $msg->network() >> / C<< $msg->network($value) >>

Type: C<Message> (L<Google::Backstory::Udm::Network>)

Network details, including sub-messages with details on each protocol
(for example, DHCP, DNS, or HTTP).

=item * C<< $msg->security_result() >> / C<< $msg->security_result($value) >>

Type: C<Message> (L<Google::Backstory::Udm::SecurityResult>)

A list of security results.

=back

=head3 Enum: Noun::Platform

=over 4

=item * C<UNKNOWN_PLATFORM> => C<0>

=item * C<WINDOWS> => C<1>

=item * C<MAC> => C<2>

=item * C<LINUX> => C<3>

=item * C<GCP> => C<4>

=item * C<AWS> => C<5>

=item * C<AZURE> => C<6>

=item * C<IOS> => C<7>

=item * C<ANDROID> => C<8>

=item * C<CHROME_OS> => C<9>

=back

=head2 Google::Backstory::Udm::Investigation

Represents the aggregated state of an investigation such as categorization,
severity, and status. Can be expanded to include analyst assignment details
and more.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->verdict() >> / C<< $msg->verdict($value) >>

Type: C<Enum> (L<Google::Backstory::Verdict>)

Describes reason a finding investigation was resolved.

=item * C<< $msg->reputation() >> / C<< $msg->reputation($value) >>

Type: C<Enum> (L<Google::Backstory::Reputation>)

Describes whether a finding was useful or not-useful.

=item * C<< $msg->severity_score() >> / C<< $msg->severity_score($value) >>

Type: C<UInt32>

Severity score for a finding set by an analyst.

=item * C<< $msg->status() >> / C<< $msg->status($value) >>

Type: C<Enum> (L<Google::Backstory::Status>)

Describes the workflow status of a finding.

=item * C<< $msg->comments() >> / C<< $msg->comments($value) >>

Type: C<String>

Comment added by the Analyst.

=item * C<< $msg->priority() >> / C<< $msg->priority($value) >>

Type: C<Enum> (L<Google::Backstory::Priority>)

Priority of the Alert or Finding set by analyst.

=item * C<< $msg->root_cause() >> / C<< $msg->root_cause($value) >>

Type: C<String>

Root cause of the Alert or Finding set by analyst.

=item * C<< $msg->reason() >> / C<< $msg->reason($value) >>

Type: C<Enum> (L<Google::Backstory::Reason>)

Reason for closing the Case or Alert.

=item * C<< $msg->risk_score() >> / C<< $msg->risk_score($value) >>

Type: C<UInt32>

Risk score for a finding set by an analyst.

=item * C<< $msg->id() >> / C<< $msg->id($value) >>

Type: C<String>

Identifier for the investigation

=back

=head2 Google::Backstory::Udm::Tags

Tags are event metadata which is set by examining event contents
post-parsing. For example, a UDM event may be assigned a tenant_id based on
certain customer-defined parameters.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->tenant_id() >> / C<< $msg->tenant_id($value) >>

Type: C<Bytes>

A list of subtenant ids that this event belongs to.

=item * C<< $msg->data_tap_config_name() >> / C<< $msg->data_tap_config_name($value) >>

Type: C<String>

A list of sink name values defined in DataTap configurations.

=back

=head2 Google::Backstory::Udm::AttackDetails

MITRE ATT&CK details.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->version() >> / C<< $msg->version($value) >>

Type: C<String>

ATT&CK version (e.g. 12.1).

=item * C<< $msg->tactics() >> / C<< $msg->tactics($value) >>

Type: C<Message> (L<Google::Backstory::Udm::AttackDetails::Tactic>)

Tactics employed.

=item * C<< $msg->techniques() >> / C<< $msg->techniques($value) >>

Type: C<Message> (L<Google::Backstory::Udm::AttackDetails::Technique>)

Techniques employed.

=back

