Domains.

=item * C<< $msg->hostname() >> / C<< $msg->hostname($value) >>

Type: C<String>

Hostnames.

=item * C<< $msg->user() >> / C<< $msg->user($value) >>

Type: C<String>

Users.

=item * C<< $msg->email() >> / C<< $msg->email($value) >>

Type: C<String>

Emails.

=item * C<< $msg->file_path() >> / C<< $msg->file_path($value) >>

Type: C<String>

File paths.

=item * C<< $msg->hash() >> / C<< $msg->hash($value) >>

Type: C<String>

File Hashes.

=item * C<< $msg->process_id() >> / C<< $msg->process_id($value) >>

Type: C<String>

Process Identifiers.

=back

